import React from 'react'
import { Heading, Flex, Text, Skeleton, EagleChartIcon, CommunityIcon, SwapIcon, NoProfileAvatarIcon, EagleAvatarIcon } from '@pancakeswap/uikit'
import { useTranslation } from 'contexts/Localization'
import { useGetStats } from 'hooks/api'
import useTheme from 'hooks/useTheme'
import { formatLocalisedCompactNumber } from 'utils/formatBalance'
import styled from 'styled-components'
import IconCard, { IconCardData } from '../IconCard'
import StatCardContent from './StatCardContent'
import { useTotalValue } from '../../../../state/hooks'
// import GradientLogo from '../GradientLogoSvg'

// Values fetched from bitQuery effective 13/8/21
const txCount = 1500
const addressCount = 132

const StyledNoProfileAvatarIcon = styled(NoProfileAvatarIcon)`
    height: 100%;
    width: 100%;
  `
const StyledEagleAvatarIcon = styled(EagleAvatarIcon)`
    height: 100%;
    width: 100%;
  `
const Sticker = styled(Flex)`
  height: 92px;
  width: 92px;
  box-shadow: ${({ theme }) => theme.card.boxShadow};
  background-color: ${({ theme }) => theme.colors.invertedContrast};
  border-radius: ${({ theme }) => theme.radii.circle};
  border: 3px solid ${({ theme }) => theme.colors.invertedContrast};
`

const EagleSticker = styled(Flex)`
  height: 192px;
  width: 192px;
`

const Stats = () => {
  const { t } = useTranslation()
  // const data = useGetStats()
  const { theme } = useTheme()

  // const tvlString = data ? formatLocalisedCompactNumber(data.tvl) : '-'
  const totalValueBignumber = useTotalValue();
  const totalValue = totalValueBignumber.toFixed(0);
  const trades = formatLocalisedCompactNumber(txCount)
  const users = formatLocalisedCompactNumber(addressCount)

  const tvlText = t('And those users are now entrusting the platform with over $%tvl% in funds.', { tvl: totalValue })
  const [entrusting, inFunds] = tvlText.split(totalValue)

  const UsersCardData: IconCardData = {
    icon: <CommunityIcon color="secondary" width="36px" />,
  }

  const TradesCardData: IconCardData = {
    icon: <SwapIcon color="primary" width="36px" />,
  }

  const StakedCardData: IconCardData = {
    icon: <EagleChartIcon color="primary" width="36px" />,
  }

  return (
    <Flex justifyContent="center" alignItems="center" flexDirection="column">
      {/* <GradientLogo height="48px" width="48px" mb="24px" /> */}
      {/* <Sticker><StyledNoProfileAvatarIcon /></Sticker> */}
      <EagleSticker><StyledEagleAvatarIcon /></EagleSticker>
      <Heading textAlign="center" scale="xl">
        {t('Trusted by users.')}
      </Heading>
      <Heading textAlign="center" scale="xl" mb="32px">
        {t('Empowered by innovation.')}
      </Heading>
      <Text textAlign="center" color="textSubtle" bold mb="32px">
        {t('MDex, also known as Magicdex, launched in 2024, is committed to providing secure and transparent services. As we begin our journey, we are eager to build a trusted platform with you.')}
      </Text>
      {/* <Flex flexWrap="wrap">
        <Text display="inline" textAlign="center" color="textSubtle" mb="20px">
          {entrusting}
          <>{totalValue ? <>{totalValue}</> : <Skeleton display="inline-block" height={16} width={70} mt="2px" />}</>
          {inFunds}
        </Text>
      </Flex> */}

      {/* <Text textAlign="center" color="textSubtle" bold mb="32px">
        {t('Will you join them?')}
      </Text> */}

      <Flex flexDirection={['column', null, null, 'row']}>
        <IconCard {...UsersCardData} mr={[null, null, null, '16px']} mb={['16px', null, null, '0']}>
          <StatCardContent
            headingText={t('No need to register')}
            bodyText={t('Easily connect your wallet')}
            highlightColor={theme.colors.secondary}
          />
        </IconCard>
        <IconCard {...TradesCardData} mr={[null, null, null, '16px']} mb={['16px', null, null, '0']}>
          <StatCardContent
            headingText={t('Trade what you like')}
            bodyText={t('Swap any token instantly')}
            highlightColor={theme.colors.primary}
          />
        </IconCard>
        <IconCard {...StakedCardData}>
          <StatCardContent
            headingText={t('Simple')}
            bodyText={t('Manage and use your crypto assets seamlessly')}
            highlightColor={theme.colors.primary}
          />
        </IconCard>
      </Flex>
    </Flex>
  )
}

export default Stats
